  [1220316] = { "Quando lanci Innervazione su un altro giocatore, viene lanciata anche su di te.", nil, 0xc5166339, nil, "um" },
  [1220318] = { "Lanciare Tocco Curativo o Nutrizione ti dà una probabilità del $N1% di ottenere mana pari al $N2% del costo base dell'incantesimo.", nil, 0xc516a2ab, nil, "um" },
